public class GalleryDataProvider : IImageGalleryDataProvider
{
    private readonly IImageService _imageService;

    public async Task<PagedResult<IGalleryImage>> GetImagesAsync(
        int page, int pageSize, string? searchText = null, 
        CancellationToken ct = default)
    {
        var result = await _imageService.GetImagesAsync(
            page, pageSize, searchText, ct);

        return new PagedResult<IGalleryImage>
        {
            Items = result.Items.Select(i => new GalleryImage
            {
                Id = i.Id,
                ThumbnailUrl = i.ThumbnailUrl,
                FullSizeUrl = i.FullSizeUrl,
                Title = i.Title,
                Description = i.Description
            }).ToList(),
            TotalCount = result.TotalCount
        };
    }
}
